
using MySqlConnector;

namespace Infrastructure.Scheduling;

/// <summary>
/// Quartz 集群存储初始化（P1-A4）：确保 MySQL 中 QRTZ_* 11 张集群表存在（幂等、并发安全）。
/// <para>本服务器默认存储引擎为 MyISAM（无行锁语义），QRTZ_LOCKS 等表显式 ENGINE=InnoDB 以保证集群锁有效。</para>
/// <para>所有 DDL 均用 <c>CREATE TABLE IF NOT EXISTS</c> 且索引内联在表定义中：
/// 多副本并发冷启动时 MySQL 以 metadata lock 串行化同名建表，未抢到的实例收到 warning 而非异常，
/// 因此无需额外的分布式锁，也不会出现「check-then-create 竞态 → 第二实例启动失败」。</para>
/// <para>本类型是纯静态工具：宿主在「结构就绪后、任务装载前」于 <c>Program.cs</c> 显式调用一次
/// （<c>IHostedService</c> 要等 <c>app.Run()</c> 才启动，赶不上启动块里的调度器初始化），
/// 不再注册为宿主服务，避免一次启动重复执行。</para>
/// </summary>
public static class QuartzSchemaInitializer
{
    /// <summary>Quartz 官方 QRTZ_ 表数量（含 QRTZ_LOCKS）；用于判定结构是否完整。</summary>
    private const int ExpectedTableCount = 11;

    /// <summary>
    /// Quartz.NET 3.x MySQL 集群表结构（11 表 + 官方索引，转 InnoDB + utf8mb4）。
    /// <para>索引内联为表定义中的 KEY 子句：MySQL 不支持 <c>CREATE INDEX IF NOT EXISTS</c>，
    /// 内联后随 <c>CREATE TABLE IF NOT EXISTS</c> 一并原子创建，天然幂等且并发安全。</para>
    /// </summary>
    private const string SchemaDdl =
        """
        CREATE TABLE IF NOT EXISTS QRTZ_JOB_DETAILS(SCHED_NAME VARCHAR(120) NOT NULL,JOB_NAME VARCHAR(190) NOT NULL,JOB_GROUP VARCHAR(190) NOT NULL,DESCRIPTION VARCHAR(250) NULL,JOB_CLASS_NAME VARCHAR(250) NOT NULL,IS_DURABLE VARCHAR(1) NOT NULL,IS_NONCONCURRENT VARCHAR(1) NOT NULL,IS_UPDATE_DATA VARCHAR(1) NOT NULL,REQUESTS_RECOVERY VARCHAR(1) NOT NULL,JOB_DATA BLOB NULL,PRIMARY KEY(SCHED_NAME,JOB_NAME,JOB_GROUP),KEY IDX_QRTZ_J_REQ_RECOVERY(SCHED_NAME,REQUESTS_RECOVERY),KEY IDX_QRTZ_J_GRP(SCHED_NAME,JOB_GROUP)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        CREATE TABLE IF NOT EXISTS QRTZ_TRIGGERS(SCHED_NAME VARCHAR(120) NOT NULL,TRIGGER_NAME VARCHAR(190) NOT NULL,TRIGGER_GROUP VARCHAR(190) NOT NULL,JOB_NAME VARCHAR(190) NOT NULL,JOB_GROUP VARCHAR(190) NOT NULL,DESCRIPTION VARCHAR(250) NULL,NEXT_FIRE_TIME BIGINT NULL,PREV_FIRE_TIME BIGINT NULL,PRIORITY INTEGER NULL,TRIGGER_STATE VARCHAR(16) NOT NULL,TRIGGER_TYPE VARCHAR(8) NOT NULL,START_TIME BIGINT NOT NULL,END_TIME BIGINT NULL,CALENDAR_NAME VARCHAR(190) NULL,MISFIRE_INSTR SMALLINT NULL,JOB_DATA BLOB NULL,PRIMARY KEY(SCHED_NAME,TRIGGER_NAME,TRIGGER_GROUP),KEY IDX_QRTZ_T_J(SCHED_NAME,JOB_NAME,JOB_GROUP),KEY IDX_QRTZ_T_JG(SCHED_NAME,JOB_GROUP),KEY IDX_QRTZ_T_C(SCHED_NAME,CALENDAR_NAME),KEY IDX_QRTZ_T_G(SCHED_NAME,TRIGGER_GROUP),KEY IDX_QRTZ_T_STATE(SCHED_NAME,TRIGGER_STATE),KEY IDX_QRTZ_T_N_STATE(SCHED_NAME,TRIGGER_NAME,TRIGGER_GROUP,TRIGGER_STATE),KEY IDX_QRTZ_T_N_G_STATE(SCHED_NAME,TRIGGER_GROUP,TRIGGER_STATE),KEY IDX_QRTZ_T_NEXT_FIRE_TIME(SCHED_NAME,NEXT_FIRE_TIME),KEY IDX_QRTZ_T_NFT_ST(SCHED_NAME,TRIGGER_STATE,NEXT_FIRE_TIME),KEY IDX_QRTZ_T_NFT_MISFIRE(SCHED_NAME,MISFIRE_INSTR,NEXT_FIRE_TIME),KEY IDX_QRTZ_T_NFT_ST_MISFIRE(SCHED_NAME,MISFIRE_INSTR,NEXT_FIRE_TIME,TRIGGER_STATE),KEY IDX_QRTZ_T_NFT_ST_MISFIRE_GRP(SCHED_NAME,TRIGGER_GROUP,TRIGGER_STATE,NEXT_FIRE_TIME,MISFIRE_INSTR),FOREIGN KEY(SCHED_NAME,JOB_NAME,JOB_GROUP) REFERENCES QRTZ_JOB_DETAILS(SCHED_NAME,JOB_NAME,JOB_GROUP)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        CREATE TABLE IF NOT EXISTS QRTZ_SIMPLE_TRIGGERS(SCHED_NAME VARCHAR(120) NOT NULL,TRIGGER_NAME VARCHAR(190) NOT NULL,TRIGGER_GROUP VARCHAR(190) NOT NULL,REPEAT_COUNT BIGINT NOT NULL,REPEAT_INTERVAL BIGINT NOT NULL,TIMES_TRIGGERED BIGINT NOT NULL,PRIMARY KEY(SCHED_NAME,TRIGGER_NAME,TRIGGER_GROUP),FOREIGN KEY(SCHED_NAME,TRIGGER_NAME,TRIGGER_GROUP) REFERENCES QRTZ_TRIGGERS(SCHED_NAME,TRIGGER_NAME,TRIGGER_GROUP)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        CREATE TABLE IF NOT EXISTS QRTZ_CRON_TRIGGERS(SCHED_NAME VARCHAR(120) NOT NULL,TRIGGER_NAME VARCHAR(190) NOT NULL,TRIGGER_GROUP VARCHAR(190) NOT NULL,CRON_EXPRESSION VARCHAR(120) NOT NULL,TIME_ZONE_ID VARCHAR(80),PRIMARY KEY(SCHED_NAME,TRIGGER_NAME,TRIGGER_GROUP),FOREIGN KEY(SCHED_NAME,TRIGGER_NAME,TRIGGER_GROUP) REFERENCES QRTZ_TRIGGERS(SCHED_NAME,TRIGGER_NAME,TRIGGER_GROUP)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        CREATE TABLE IF NOT EXISTS QRTZ_SIMPROP_TRIGGERS(SCHED_NAME VARCHAR(120) NOT NULL,TRIGGER_NAME VARCHAR(190) NOT NULL,TRIGGER_GROUP VARCHAR(190) NOT NULL,STR_PROP_1 VARCHAR(512) NULL,STR_PROP_2 VARCHAR(512) NULL,STR_PROP_3 VARCHAR(512) NULL,INT_PROP_1 INT NULL,INT_PROP_2 INT NULL,LONG_PROP_1 BIGINT NULL,LONG_PROP_2 BIGINT NULL,DEC_PROP_1 NUMERIC(13,4) NULL,DEC_PROP_2 NUMERIC(13,4) NULL,BOOL_PROP_1 VARCHAR(1) NULL,BOOL_PROP_2 VARCHAR(1) NULL,PRIMARY KEY(SCHED_NAME,TRIGGER_NAME,TRIGGER_GROUP),FOREIGN KEY(SCHED_NAME,TRIGGER_NAME,TRIGGER_GROUP) REFERENCES QRTZ_TRIGGERS(SCHED_NAME,TRIGGER_NAME,TRIGGER_GROUP)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        CREATE TABLE IF NOT EXISTS QRTZ_BLOB_TRIGGERS(SCHED_NAME VARCHAR(120) NOT NULL,TRIGGER_NAME VARCHAR(190) NOT NULL,TRIGGER_GROUP VARCHAR(190) NOT NULL,BLOB_DATA BLOB NULL,PRIMARY KEY(SCHED_NAME,TRIGGER_NAME,TRIGGER_GROUP),FOREIGN KEY(SCHED_NAME,TRIGGER_NAME,TRIGGER_GROUP) REFERENCES QRTZ_TRIGGERS(SCHED_NAME,TRIGGER_NAME,TRIGGER_GROUP)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        CREATE TABLE IF NOT EXISTS QRTZ_CALENDARS(SCHED_NAME VARCHAR(120) NOT NULL,CALENDAR_NAME VARCHAR(190) NOT NULL,CALENDAR BLOB NOT NULL,PRIMARY KEY(SCHED_NAME,CALENDAR_NAME)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        CREATE TABLE IF NOT EXISTS QRTZ_PAUSED_TRIGGER_GRPS(SCHED_NAME VARCHAR(120) NOT NULL,TRIGGER_GROUP VARCHAR(190) NOT NULL,PRIMARY KEY(SCHED_NAME,TRIGGER_GROUP)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        CREATE TABLE IF NOT EXISTS QRTZ_FIRED_TRIGGERS(SCHED_NAME VARCHAR(120) NOT NULL,ENTRY_ID VARCHAR(95) NOT NULL,TRIGGER_NAME VARCHAR(190) NOT NULL,TRIGGER_GROUP VARCHAR(190) NOT NULL,INSTANCE_NAME VARCHAR(190) NOT NULL,FIRED_TIME BIGINT NOT NULL,SCHED_TIME BIGINT NOT NULL,PRIORITY INTEGER NOT NULL,STATE VARCHAR(16) NOT NULL,JOB_NAME VARCHAR(190) NULL,JOB_GROUP VARCHAR(190) NULL,IS_NONCONCURRENT VARCHAR(1) NULL,REQUESTS_RECOVERY VARCHAR(1) NULL,PRIMARY KEY(SCHED_NAME,ENTRY_ID),KEY IDX_QRTZ_FT_TRIG_INST_NAME(SCHED_NAME,INSTANCE_NAME),KEY IDX_QRTZ_FT_INST_JOB_REQ_RECOVERY(SCHED_NAME,INSTANCE_NAME,REQUESTS_RECOVERY),KEY IDX_QRTZ_FT_J_G(SCHED_NAME,JOB_NAME,JOB_GROUP),KEY IDX_QRTZ_FT_JG(SCHED_NAME,JOB_GROUP),KEY IDX_QRTZ_FT_T_G(SCHED_NAME,TRIGGER_NAME,TRIGGER_GROUP),KEY IDX_QRTZ_FT_TG(SCHED_NAME,TRIGGER_GROUP),KEY IDX_QRTZ_FT_TRIG_NAME(SCHED_NAME,TRIGGER_NAME)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        CREATE TABLE IF NOT EXISTS QRTZ_SCHEDULER_STATE(SCHED_NAME VARCHAR(120) NOT NULL,INSTANCE_NAME VARCHAR(190) NOT NULL,LAST_CHECKIN_TIME BIGINT NOT NULL,CHECKIN_INTERVAL BIGINT NOT NULL,PRIMARY KEY(SCHED_NAME,INSTANCE_NAME)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        CREATE TABLE IF NOT EXISTS QRTZ_LOCKS(SCHED_NAME VARCHAR(120) NOT NULL,LOCK_NAME VARCHAR(40) NOT NULL,PRIMARY KEY(SCHED_NAME,LOCK_NAME)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        """;

    /// <summary>
    /// 确保 QRTZ_* 集群表存在（幂等、并发安全）：11 张表齐全即直接返回；
    /// 缺表时逐条执行 <c>CREATE TABLE IF NOT EXISTS</c>，即使多个副本同时判定「缺表」也不会互相冲突。
    /// </summary>
    /// <param name="connectionString">数据库连接串。</param>
    /// <param name="cancellationToken">取消令牌。</param>
    public static async Task EnsureSchemaAsync(string connectionString, CancellationToken cancellationToken = default)
    {
        await using var connection = new MySqlConnection(connectionString);
        await connection.OpenAsync(cancellationToken);

        // 完整性判定（而非仅看 QRTZ_LOCKS）：上次初始化中途失败留下部分表时也能自愈补齐
        await using (var probe = connection.CreateCommand())
        {
            probe.CommandText =
                "SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() " +
                "AND TABLE_NAME IN ('QRTZ_JOB_DETAILS','QRTZ_TRIGGERS','QRTZ_SIMPLE_TRIGGERS','QRTZ_CRON_TRIGGERS'," +
                "'QRTZ_SIMPROP_TRIGGERS','QRTZ_BLOB_TRIGGERS','QRTZ_CALENDARS','QRTZ_PAUSED_TRIGGER_GRPS'," +
                "'QRTZ_FIRED_TRIGGERS','QRTZ_SCHEDULER_STATE','QRTZ_LOCKS')";
            var count = Convert.ToInt32(await probe.ExecuteScalarAsync(cancellationToken));
            if (count == ExpectedTableCount)
            {
                return;
            }
        }

        foreach (var statement in SchemaDdl.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            await using var command = connection.CreateCommand();
            command.CommandText = statement;
            await command.ExecuteNonQueryAsync(cancellationToken);
        }
    }
}
